const openArtwork=createArtworkViewer();
const galleryPageSize=24;
let galleryPage=0;
function renderGallery(){
 const q=$('gallerySearch').value.trim().toLowerCase(),filter=$('galleryFilter').value;
 const administrator=adminPreview.state().active,inventory=galleryInventory(publishedEditions,previewEditions,{administrator});
 $('galleryDescription').textContent=administrator?'ADMINISTRATOR PREVIEW · all prepared artworks, including unminted editions.':'Minted island artworks. The first collected islands will appear here after minting.';
 $('galleryStats').innerHTML='<div><small>'+(administrator?'PREVIEW EDITIONS':'MINTED EDITIONS')+'</small>'+inventory.length+'</div><div><small>ISLANDS</small>'+new Set(inventory.map(e=>e.islandId)).size+'</div>';
 const grid=$('galleryGrid');grid.replaceChildren();
 let pager=$('galleryPagination');
 if(!pager){pager=document.createElement('div');pager.id='galleryPagination';pager.className='gallery-pagination';grid.after(pager)}
 pager.replaceChildren();
 const matches=inventory.filter(e=>[e.name,e.mood,e.id,e.collection||''].join(' ').toLowerCase().includes(q)&&(filter==='All'||e.status===filter));
 if(!matches.length){const empty=document.createElement('article');empty.className='galleryempty';empty.textContent=!inventory.length&&!administrator?'No islands have been minted yet. Explore the map in Atlas or browse names and data in the Index.':'No matching editions';grid.append(empty);return;}
 const pages=Math.ceil(matches.length/galleryPageSize);galleryPage=Math.min(galleryPage,pages-1);
 for(const e of matches.slice(galleryPage*galleryPageSize,(galleryPage+1)*galleryPageSize)){
  const card=document.createElement('article');card.className='galleryedition';
  const visible=administrator||hasVerifiedMint(e);
  const preview=document.createElement('button');preview.type='button';preview.className='artwork-preview';preview.setAttribute('aria-label','Enlarge '+e.name+' '+e.orientation);preview.setAttribute('aria-haspopup','dialog');preview.onclick=()=>visible?openArtwork(e):openEdition(e.id,{fromIndex:true});
  const img=document.createElement('img');if(visible)img.src='/thumbnails/'+e.id+'.webp';img.alt=e.name+' '+e.orientation;img.width=640;img.height=640;img.loading='lazy';img.decoding='async';if(visible)preview.append(img);else{preview.removeAttribute('aria-haspopup');preview.setAttribute('aria-label','View '+e.name+' details');preview.append(artworkMystery('Artwork revealed after mint'))}
  const title=document.createElement('h2');title.textContent=e.name;
  const meta=document.createElement('p');meta.textContent=e.id+' · '+e.orientation+(visible?' · '+e.mood:'');
  const status=document.createElement('p');status.className='edition-status-summary';const state=editionStatus({artworkExists:true,collectionReleased,chain:e.chain});status.textContent=state.artwork+' · '+state.mint;status.setAttribute('aria-label','Artwork: '+state.artwork+'; Mint: '+state.mint);
  card.append(preview,title,meta,status);
  const actions=document.createElement('div');actions.className='artwork-actions';
  const view=document.createElement('a');view.className='artwork-link';view.href=editionUrl(e.id,location.origin,{fromIndex:true});view.textContent='View island';view.onclick=event=>{event.preventDefault();openEdition(e.id,{fromIndex:true})};
  actions.append(view);card.append(actions,acquisitionButtons(state,e));
  if(['Collected','On Sale'].includes(e.status)){const tip=document.createElement('div');tip.className='gallerytip';tip.innerHTML='<strong>🥂 Cheers to your Island</strong><small>100% to the verified current owner</small><div class="tokens"><button disabled>250 CHEERS</button><button disabled>500 CHEERS</button></div><small>Payments not active yet.</small>';card.append(tip)}
  grid.append(card);
 }
 if(pages>1){
  const previous=document.createElement('button'),next=document.createElement('button'),label=document.createElement('span');
  previous.className=next.className='outline';previous.textContent='← Previous';next.textContent='Next →';previous.disabled=galleryPage===0;next.disabled=galleryPage===pages-1;
  label.textContent='Page '+(galleryPage+1)+' of '+pages+' · '+matches.length+' editions';label.setAttribute('aria-live','polite');
  const changePage=step=>{galleryPage+=step;renderGallery();grid.scrollIntoView({block:'start'})};
  previous.onclick=()=>changePage(-1);next.onclick=()=>changePage(1);pager.append(previous,label,next);
 }
}
$('gallerySearch').oninput=()=>{galleryPage=0;renderGallery()};$('galleryFilter').onchange=()=>{galleryPage=0;renderGallery()};renderGallery();
$('cheersRanking').onchange=()=>{$('cheersRankTitle').textContent=$('cheersRanking').value};
