const areaFormat=new Intl.NumberFormat('en-US');
function islandDetails(name,record=registry.find(r=>r[0]===name)){
 const fact=record?.[5]?null:islandFacts[name];
 const details=document.createElement('dl');details.className='island-geography edition-traits';
 const fields=new Map();
 const field=(label,value)=>{let dd=fields.get(label);if(!dd){const dt=document.createElement('dt');dt.textContent=label;dd=document.createElement('dd');details.append(dt,dd);fields.set(label,dd)}dd.textContent=value};
 field('Country / territory',fact?.sovereignty??record?.[1]??'Not recorded');
 field('Area',Number.isFinite(fact?.area)?areaFormat.format(fact.area)+' km² (approx.)':'Not verified');
 if(record&&Number.isFinite(record[3])&&Number.isFinite(record[4]))field('Coordinates',record[3].toFixed(5)+', '+record[4].toFixed(5));
 if(record?.[5]){const dd=document.createElement('dd'),dt=document.createElement('dt'),link=document.createElement('a');dt.textContent='Source';link.href='https://www.geonames.org/'+record[5].split(':')[1];link.textContent=record[5];link.target='_blank';link.rel='noopener';dd.append(link);details.append(dt,dd)}
 const enrich=async()=>{
  const review=await reviewReady;
  let facts=record?.[5]?null:review?.curated?.[name];
  if(record?.[5]){
   const id=record[5].split(':')[1],shard=Number(id)%32;
   if(!detailShards.has(shard))detailShards.set(shard,fetch('/data/island-details/'+shard+'.json').then(r=>{if(!r.ok)throw Error();return r.json()}).catch(()=>null));
   facts=(await detailShards.get(shard))?.records?.[id];
  }
  if(!Number.isFinite(fact?.area)&&Number.isFinite(facts?.areaKm2)){
   field('Area',areaFormat.format(facts.areaKm2)+' km² (approx.)');
   field('Area source',record?.[5]?'GSHHG 2.3.7 · shoreline polygon estimate':String(facts.areaSource||'Artwork geometry · approximate'));
  }
  if(facts?.waterType)field('Water type',facts.waterType);
 };
 enrich();return details;
}
