const islandMarkers=L.layerGroup().addTo(worldMap);
function mapRows(){
 const q=$('atlasSearch').value.toLowerCase().trim(),filter=$('atlasFilter').value;
 return registry.filter(row=>{
  if(!row.slice(0,3).join(' ').toLowerCase().includes(q))return false;
  const exists=previewEditions.some(e=>e.name===row[0]),minted=publishedEditions.some(e=>e.name===row[0]&&hasVerifiedMint(e));
  return filter==='All'||filter==='Artwork exists'&&exists||filter==='Artwork not created'&&!exists||filter==='Minted'&&minted;
 });
}
function renderMap(){
 islandMarkers.clearLayers();for(const row of mapRows()){
  const [name,country,,lat,lon]=row,popup=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('p'),button=document.createElement('button');
  title.textContent=name;sub.textContent=country;button.textContent='Open island details';button.onclick=()=>openIsland(row,null,{fromIndex:true});popup.append(title,sub,button);
  L.circleMarker([lat,lon],{radius:6,color:'#c4e8ee',fillColor:'#758794',fillOpacity:1,weight:2}).bindPopup(popup).addTo(islandMarkers);
 }
}
function renderAtlas(){renderMap();$('atlasStats').innerHTML='<div><small>ON THIS MAP</small>'+mapRows().length+'</div><div><small>WITH ARTWORK</small>'+new Set(previewEditions.map(e=>e.islandId)).size+'</div><div><small>MINTED</small>'+new Set(publishedEditions.filter(hasVerifiedMint).map(e=>e.islandId)).size+'</div>'}
$('atlasSearch').oninput=renderAtlas;$('atlasFilter').onchange=renderAtlas;renderAtlas();
